const { MinPriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");

function networkDelayTime(adj, source) {
  const dist = new Array(adj.length).fill(Infinity);
  dist[source] = 0;
  // The entries are [time, node] pairs, and dequeue gives the smallest time.
  const heap = new MinPriorityQueue((entry) => entry[0]);
  heap.enqueue([0, source]);
  while (!heap.isEmpty()) {
    const [time, node] = heap.dequeue();
    if (time > dist[node]) {
      continue; // an old entry: node was already reached sooner
    }
    for (const [neighbor, w] of adj[node]) {
      if (time + w < dist[neighbor]) {
        dist[neighbor] = time + w;
        heap.enqueue([time + w, neighbor]);
      }
    }
  }
  const slowest = Math.max(...dist);
  return slowest === Infinity ? -1 : slowest;
}

