#include <algorithm>
#include <functional>
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>

// A link is {v, w}, and a heap entry is {time, node}.
using Pair = std::pair<int, int>;

int networkDelayTime(const std::vector<std::vector<Pair>>& adj, int source) {
    const int INF = std::numeric_limits<int>::max();
    std::vector<int> dist(adj.size(), INF);
    dist[source] = 0;
    // std::greater makes it a min heap: the smallest time is on top.
    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> heap;
    heap.push({0, source});
    while (!heap.empty()) {
        auto [time, node] = heap.top();
        heap.pop();
        if (time > dist[node]) {
            continue; // an old entry: node was already reached sooner
        }
        for (const auto& [neighbor, w] : adj[node]) {
            if (time + w < dist[neighbor]) {
                dist[neighbor] = time + w;
                heap.push({time + w, neighbor});
            }
        }
    }
    int slowest = *std::max_element(dist.begin(), dist.end());
    return slowest == INF ? -1 : slowest;
}

int main() {
    int n, m;
    std::cin >> n >> m;
    // adj[u] holds {v, w} for each link from u to v that takes w.
    std::vector<std::vector<Pair>> adj(n);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        std::cin >> u >> v >> w;
        adj[u].push_back({v, w});
    }
    int source;
    std::cin >> source;
    std::cout << networkDelayTime(adj, source) << "\n";
    return 0;
}

