import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    static int networkDelayTime(List<List<int[]>> adj, int source) {
        int[] dist = new int[adj.size()];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        // The entries are {time, node}, and poll gives the smallest time.
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        heap.add(new int[] {0, source});
        while (!heap.isEmpty()) {
            int[] entry = heap.poll();
            int time = entry[0];
            int node = entry[1];
            if (time > dist[node]) {
                continue; // an old entry: node was already reached sooner
            }
            for (int[] link : adj.get(node)) {
                int neighbor = link[0];
                int arrival = time + link[1];
                if (arrival < dist[neighbor]) {
                    dist[neighbor] = arrival;
                    heap.add(new int[] {arrival, neighbor});
                }
            }
        }
        int slowest = 0;
        for (int d : dist) {
            if (d == Integer.MAX_VALUE) {
                return -1;
            }
            slowest = Math.max(slowest, d);
        }
        return slowest;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        // adj.get(u) holds {v, w} for each link from u to v that takes w.
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            int w = in.nextInt();
            adj.get(u).add(new int[] {v, w});
        }
        int source = in.nextInt();
        System.out.println(networkDelayTime(adj, source));
    }
}

