package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"math"
	"os"
)

// timeHeap implements heap.Interface with the smallest time on top. Its
// items are [time, node] pairs.
type timeHeap [][2]int

func (h timeHeap) Len() int            { return len(h) }
func (h timeHeap) Less(i, j int) bool  { return h[i][0] < h[j][0] }
func (h timeHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *timeHeap) Push(x interface{}) { *h = append(*h, x.([2]int)) }
func (h *timeHeap) Pop() interface{} {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func networkDelayTime(adj [][][2]int, source int) int {
	dist := make([]int, len(adj))
	for i := range dist {
		dist[i] = math.MaxInt64
	}
	dist[source] = 0
	h := &timeHeap{{0, source}}
	for h.Len() > 0 {
		entry := heap.Pop(h).([2]int)
		time, node := entry[0], entry[1]
		if time > dist[node] {
			continue // an old entry: node was already reached sooner
		}
		for _, link := range adj[node] {
			neighbor, arrival := link[0], time+link[1]
			if arrival < dist[neighbor] {
				dist[neighbor] = arrival
				heap.Push(h, [2]int{arrival, neighbor})
			}
		}
	}
	slowest := 0
	for _, d := range dist {
		if d == math.MaxInt64 {
			return -1
		}
		if d > slowest {
			slowest = d
		}
	}
	return slowest
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	// adj[u] holds [v, w] for each link from u to v that takes w.
	adj := make([][][2]int, n)
	for i := 0; i < m; i++ {
		var u, v, w int
		fmt.Fscan(reader, &u, &v, &w)
		adj[u] = append(adj[u], [2]int{v, w})
	}
	var source int
	fmt.Fscan(reader, &source)
	fmt.Println(networkDelayTime(adj, source))
}

